        torqueSpecs: [ { part: "Oil Drain Plug", value: "30 Nm", note: "Replace copper crush washer." }, { part: "Spark Plugs", value: "25 Nm", note: "Do not overtighten." }, { part: "Wheel Bolts", value: "120 Nm", note: "Star pattern." }, { part: "Valve Cover Nuts", value: "10 Nm", note: "Tighten evenly, very prone to snapping the studs." }, { part: "Timing Belt Tensioner Nut", value: "45 Nm", note: "Tighten carefully." }, { part: "Water Pump Bolts", value: "20 Nm", note: "Tighten in crisscross pattern." }, { part: "Intake Manifold Bolts", value: "25 Nm", note: "Use new gasket." } ],
        engineeringData: { blockDesign: "Cast Iron inline-4 closed deck (EA827). Widely regarded as one of the most bulletproof blocks of the 90s.", crankshaft: "Forged Steel.", pistonSpeed: "13.8 m/s @ 5400 RPM.", alternator: "90 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy. Slightly higher compression (10.4:1) than the AAE.", wristPinDiameter: "20 mm", connectingRodLength: "144 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "54.0 mm", crankRodJournal: "47.8 mm", rodRatio: "1.67" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "Low-flow 2-valve per cylinder (8V SOHC).", valveSizes: "Intake: 40.0 mm / Exhaust: 33.0 mm.", valveStemDiameter: "8.0 mm.", camshaftDuration: "Single Overhead Camshaft.", lifterType: "Hydraulic Lifters.", specialFeature: "Non-crossflow head design (intake and exhaust on the same side). Multi-point fuel rail." }, oilAndCooling: { oilSquirters: "No", oilPumpType: "Intermediate shaft driven gear pump.", thermostatOpening: "87°C.", oilCooler: "Water-to-Oil heat exchanger at filter base." }, fuelSystem: { systemType: "Multi-Point Injection (Digifant).", maxPressure: "3.0 Bar (Fuel Rail).", injectors: "4x Electronic Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "Approx. 350 Nm (Bottom end limit).", maxSafePowerStock: "Approx. 200 hp.", maxSafeRPM: "6200 RPM", weakestLink: "The 8-valve head and archaic Air Flow Meter completely restrict natural aspiration tuning." }, electrical: { coils: "Single square ignition coil with mechanical distributor.", ecu: "Bosch Digifant" } },
