        torqueSpecs: [ { part: "Oil Drain Plug", value: "30 Nm", note: "Replace copper crush washer." }, { part: "Spark Plugs", value: "30 Nm", note: "Torque carefully into the aluminum heads." }, { part: "Wheel Bolts", value: "120 Nm", note: "Star pattern." }, { part: "Valve Cover Nuts", value: "10 Nm", note: "Tighten evenly in a crisscross pattern." }, { part: "Timing Belt Tensioner Nut", value: "25 Nm", note: "Tighten carefully." }, { part: "Water Pump Bolts", value: "20 Nm", note: "Tighten evenly." }, { part: "Valley Pan Bolts", value: "15 Nm", note: "Under the intake manifold." }, { part: "Intake Manifold Bolts", value: "20 Nm", note: "Use new gaskets." } ],
        engineeringData: { blockDesign: "All-Aluminum 90-degree V8 closed deck (PT/ABH evolution). A massive, imposing engine that barely fits in the C4 engine bay.", crankshaft: "Forged Steel, cross-plane design.", pistonSpeed: "15.5 m/s @ 6000 RPM.", alternator: "120 Amp or 150 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy.", wristPinDiameter: "22 mm", connectingRodLength: "154 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "54.0 mm", rodRatio: "1.79" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-flow 4-valve per cylinder (32V DOHC).", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "Quad Camshafts. Intake cams driven by internal chains from the exhaust cams.", lifterType: "Hydraulic Lifters.", specialFeature: "Variable Length Intake Manifold for broadening the torque curve." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Crankshaft driven gear pump.", thermostatOpening: "87°C. Buried deeply behind the timing belt.", oilCooler: "Water-to-Oil heat exchanger." }, fuelSystem: { systemType: "Multi-Point Injection (Motronic).", maxPressure: "4.0 Bar (Base Fuel Pressure).", injectors: "8x Bosch EV1 style." }, tuningLimits: { maxSafeTorqueStock: "Approx. 500 Nm (Connecting rod limit).", maxSafePowerStock: "Approx. 350 hp.", maxSafeRPM: "6800 RPM", weakestLink: "Naturally aspirated architecture entirely restricts power gains. The automatic transmission is the hard mechanical limit." }, electrical: { coils: "2x Ignition Coils feeding 2x Mechanical Distributors.", ecu: "Bosch Motronic" } },
        recommendedParts: { description: "The AEC V8 requires a massive budget. Focus heavily on resealing the oil leaks, overhauling the archaic ignition system, and replacing the timing belt perfectly.", parts: [ { category: "Timing Belt Kit & Water Pump", brand: "Continental", note: "CT726K2 (Check VIN). Extremely complex installation." }, { category: "Valve Cover Gaskets", brand: "Elring", note: "382.750. Required for both banks. Stops exhaust fires." }, { category: "Valley Pan Gasket", brand: "Elring", note: "424.840. Cures massive oil leak under the intake." }, { category: "Distributor Caps (x2)", brand: "Bosch", note: "1 235 522 430. Must replace both." }, { category: "Distributor Rotors (x2)", brand: "Bosch", note: "1 234 332 414. Must replace both." }, { category: "Ignition Lead Set", brand: "NGK", note: "RC-VW240. Highly expensive but essential." }, { category: "Spark Plugs", brand: "NGK", note: "BKR6EKUB. Dual-ground electrode." }, { category: "Mass Air Flow Sensor", brand: "Bosch", note: "0 280 217 804. Restores rich-running issues." }, { category: "Thermostat", brand: "Mahle", note: "TX 15 87D. Change this ONLY when doing the timing belt." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "WK 830/7. Often neglected." } ] },
