            tuningPotential: [ { stage: "Stage 1", power: "190 - 200 hp", notes: "An ME7.5 ECU flash via OBD2 safely unlocks massive mid-range torque. The K03 turbo spools incredibly fast.", zeroToHundred: "7.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "215 - 230 hp", notes: "Requires a 3-inch downpipe, upgraded intake, and front-mount intercooler. The K03 is maxed out here.", zeroToHundred: "7.2s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (K04 / Hybrid)", power: "260 - 300+ hp", notes: "Requires a K04-015 turbo, 440cc injectors, uprated MAF, and an FMIC. The 19mm rods handle 300hp reliably.", zeroToHundred: "5.9s", hundredToTwoHundred: "15.0s" } ],
