            engineeringData: { blockDesign: "Cast Iron closed deck (058 block architecture). Features an external water pump driven by a secondary belt.", crankshaft: "Forged Steel.", pistonSpeed: "17.3 m/s @ 6000 RPM.", alternator: "90 - 120 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum, forged rods with 20mm wrist pins.", wristPinDiameter: "20 mm", connectingRodLength: "144 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "54.0 mm", crankRodJournal: "47.8 mm", rodRatio: "1.67" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "Legendary 'Big Port' design. Highest flowing factory 1.8 head, identical to the AEB.", valveSizes: "Intake: 26.9 mm (x3) / Exhaust: 29.9 mm (x2).", valveStemDiameter: "6.0 mm.", camshaftDuration: "20-Valve DOHC.", lifterType: "Hydraulic.", specialFeature: "5-valve per cylinder technology providing exceptional volumetric efficiency at high RPM." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Chain-driven gear pump.", thermostatOpening: "87°C.", oilCooler: "Water-to-Oil heat exchanger at filter base." }, fuelSystem: { systemType: "MPI (Multi-Point Injection).", maxPressure: "4.0 Bar (Fuel Rail).", injectors: "Bosch EV1." }, tuningLimits: { maxSafeTorqueStock: "Approx. 450 Nm.", maxSafePowerStock: "Approx. 350 hp (Internal limit).", maxSafeRPM: "7000 RPM", weakestLink: "The K03 turbo, factory fuel pump, and the archaic ICM ignition control." }, electrical: { coils: "4x Individual external coils driven by ICM.", ecu: "Bosch Motronic M3.8.3" } },
            recommendedParts: { description: "The AJL is a rare, highly sought-after factory tuned AEB. Keep the oil pickup clean and upgrade the ignition.", parts: [ { category: "Timing Belt Kit", brand: "Continental", note: "CT909K1. Replace every 90k km." }, { category: "Oil Pump & Pickup Tube", brand: "Febi Bilstein", note: "32274. Mandatory if oil pressure is unknown." }, { category: "Cam Chain Tensioner", brand: "INA", note: "553 0219 10. Prevents head rattle." }, { category: "ICM Module", brand: "Bosch", note: "0 227 100 211. Keep a spare in the glovebox." }, { category: "Spark Plugs", brand: "NGK", note: "PFR6Q. Copper BKR7E for tuned cars." }, { category: "Valve Cover Gasket", brand: "Elring", note: "382.750. Stop oil in plug wells." }, { category: "Water Pump", brand: "HEPU", note: "P542. Metal impeller." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "WK 830/7. Highly critical for fuel flow." }, { category: "Thermostat", brand: "Mahle", note: "TX 15 87D." }, { category: "Turbo Oil Feed Line", brand: "Custom", note: "Upgrade to braided stainless." } ] },
