            oemPlusUpgrades: [ { name: "Aluminum Valley Pan Gasket", description: "Replacing the factory paper/rubber valley pan gasket with a high-quality metal-reinforced version.", benefit: "Permanently cures the massive oil leak hidden beneath the intake manifold." }, { name: "Silicone PCV 'Spider Hose'", description: "Replacing the brittle plastic PCV breather assembly with a custom or reinforced silicone setup.", benefit: "Prevents vacuum leaks, stabilizes the idle, and ensures proper crankcase ventilation, which saves engine seals." }, { name: "Billet Intake Linkages", description: "Replacing the fragile plastic vacuum arms for the intake manifold changeover system with billet aluminum pieces.", benefit: "Restores low-end torque and prevents the flaps from getting stuck." }, { name: "High-Flow Catalytic Converters", description: "Replacing the ancient, restrictive factory dual cats with high-flow metallic cores.", benefit: "Restores lost power, improves fuel economy, and unleashes a deeper, more aggressive V6 rumble." } ],
