            engineeringData: { blockDesign: "Cast Iron 90-degree V6 closed deck. Features a deep skirt design for exceptional rigidity. A shorter stroke version of the 2.8L architecture.", crankshaft: "Forged Steel, cross-plane design, 4 main bearings.", pistonSpeed: "14.8 m/s @ 6000 RPM.", alternator: "120 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy.", wristPinDiameter: "21 mm", connectingRodLength: "154 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "54.0 mm", rodRatio: "1.79" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-efficiency 5-valve per cylinder (30V DOHC) architecture (3 intake, 2 exhaust).", valveSizes: "Intake: 26.9 mm (x3) / Exhaust: 29.9 mm (x2).", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad Camshafts. Intake cams driven by internal chains from the exhaust cams.", lifterType: "Hydraulic Lifters.", specialFeature: "5-valve technology developed from motorsport, drastically improving high-RPM breathing over the older 12V V6 engines." }, oilAndCooling: { oilSquirters: "Yes (Under-piston cooling jets).", oilPumpType: "Crankshaft driven internal gear pump.", thermostatOpening: "87°C. Buried deeply behind the timing belt (requires complete timing belt removal to change).", oilCooler: "Water-to-Oil heat exchanger at the oil filter base." }, fuelSystem: { systemType: "Multi-Point Injection (Motronic M5.9.2).", maxPressure: "4.0 Bar (Fuel Rail).", injectors: "6x Bosch EV1 style Electronic Solenoids." }, tuningLimits: { maxSafeTorqueStock: "Approx. 400 Nm (Connecting rod limit).", maxSafePowerStock: "Approx. 350 hp.", maxSafeRPM: "6800 RPM", weakestLink: "Naturally aspirated architecture entirely restricts power gains. The cost of supercharging exceeds the value of the vehicle." }, electrical: { coils: "Single 6-post 'wasted spark' ignition coil block.", ecu: "Bosch Motronic M5.9.2" } },
