            tuningPotential: [ { stage: "Stage 1 (De-Restriction)", power: "175 - 180 hp", notes: "The single most important mod for the ALW. An ECU flash completely removes the artificial 136hp factory restriction, restoring the engine to standard 2.4L specs and adding massive top-end breathing.", zeroToHundred: "8.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "185 - 190 hp", notes: "Requires a custom performance exhaust, high-flow catalytic converters, and a cold air intake. Produces an incredible V6 sound, but the cost vastly outweighs the power gains.", zeroToHundred: "8.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (2.7T Swap)", power: "250 - 400+ hp", notes: "Do not attempt to supercharge or turbocharge the naturally aspirated 2.4L. The only logical, financially sound way to make this car fast is to swap in the legendary 2.7T (BiTurbo) from an S4 B5.", zeroToHundred: "5.5s", hundredToTwoHundred: "15.0s" } ],
