                coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Prevents heater core blockages.", parts: ["G12 Coolant"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 - 70" } ], 
