        oilAndFilters: [ { interval: "8,000 km", timeLimit: "1 year", task: "Engine Oil", details: "Do not exceed 8k km. Turbo heat cokes oil rapidly.", parts: ["Filter", "6.0L 5W-40"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "60 - 90" }, { interval: "20,000 km", timeLimit: "2 years", task: "Air Filter", details: "Replace panel filter.", parts: ["Air Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "15 - 30" }, { interval: "40,000 km", timeLimit: "N/A", task: "Fuel Filter", details: "Located under the car.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "25 - 45" } ], 
