        oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Engine Oil", details: "Use high-quality 5W-40 to protect the delicate cam chain tensioners.", parts: ["Filter", "6.0L 5W-40"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "60 - 90" }, { interval: "20,000 km", timeLimit: "2 years", task: "Air Filter", details: "Replace panel filter.", parts: ["Air Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "15 - 30" }, { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Filter", details: "Replace pollen filter under cowl.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "15 - 30" }, { interval: "60,000 km", timeLimit: "N/A", task: "Fuel Filter", details: "Located under the car.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "25 - 45" } ], 
