    id: "apr-a6-c5", brand: "Audi", model: "A6", generation: "C5 (1997-2004)", engineCode: "APR", profileId: "apr-a6-c5", displacement: "2,771 cc", power: "193 hp (142 kW)", torque: "280 Nm", fuelType: "Petrol", cylinders: 6, valves: 30, compression: "10.6:1", yearRange: "1999-2001",
