        oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Engine Oil", details: "Use high-quality 5W-40 to protect the delicate cam chain tensioners.", parts: ["Filter", "6.0L 5W-40"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "60 - 90" }, { interval: "20,000 km", timeLimit: "2 years", task: "Air Filter", details: "Replace panel filter.", parts: ["Air Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "15 - 30" }, { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Filter", details: "Replace pollen filter under cowl.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "15 - 30" }, { interval: "60,000 km", timeLimit: "N/A", task: "Fuel Filter", details: "Located under the car.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "25 - 45" } ], 
        ignitionAndEngine: [ { interval: "90,000 km", timeLimit: "5 years", task: "Timing Belt, Water Pump & Thermostat", details: "Massive job. Entire front clip of the car must be removed into 'Service Position'.", parts: ["Timing Kit", "Pump", "Thermostat"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "500 - 800" }, { interval: "150,000 km", timeLimit: "N/A", task: "Cam Chain Tensioners", details: "Replace hydraulic tensioners and chains to prevent catastrophic pad failure.", parts: ["INA Tensioners", "Chains", "Gaskets"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "600 - 1000" }, { interval: "60,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace plugs. Check for oil inside the spark plug tubes.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 - 90" }, { interval: "100,000 km", timeLimit: "N/A", task: "PCV Spider Hose Check", details: "Replace brittle plastic PCV lines.", parts: ["Vaico PCV Hose"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 150" } ], 
        preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "N/A", task: "Throttle Body Clean", details: "Clean carbon and perform VCDS alignment. Crucial for DBW throttle.", parts: ["TB Cleaner"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 - 40" }, { interval: "100,000 km", timeLimit: "N/A", task: "Suspension Bushings", details: "The heavy iron V6 destroys front multi-link control arm bushings.", parts: ["Control Arm Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "400 - 800" } ], 
        coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Prevents heater core blockages.", parts: ["G12 Coolant"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 - 70" } ], 
        engineMechanical: [ { interval: "150,000 km", timeLimit: "N/A", task: "Valley Pan Reseal", details: "Replace gasket under intake manifold to cure massive oil leak.", parts: ["Elring Gasket"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 150" }, { interval: "100,000 km", timeLimit: "N/A", task: "Valve Cover Gaskets", details: "Replace on both banks.", parts: ["Gaskets"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 - 100" } ] 
