        engineMechanical: [ { interval: "150,000 km", timeLimit: "N/A", task: "Valley Pan Reseal", details: "Replace gasket under intake manifold to cure massive oil leak.", parts: ["Elring Gasket"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 150" }, { interval: "100,000 km", timeLimit: "N/A", task: "Valve Cover Gaskets", details: "Replace on both banks.", parts: ["Gaskets"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 - 100" } ] 
