        ignitionAndEngine: [ { interval: "90,000 km", timeLimit: "5 years", task: "Timing Belt, Water Pump & Thermostat", details: "Massive job. Entire front clip of the car must be removed into 'Service Position'.", parts: ["Timing Kit", "Pump", "Thermostat"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "500 - 800" }, { interval: "150,000 km", timeLimit: "N/A", task: "Cam Chain Tensioners", details: "Replace hydraulic tensioners and chains to prevent catastrophic pad failure.", parts: ["INA Tensioners", "Chains", "Gaskets"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "600 - 1000" }, { interval: "60,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace plugs. Check for oil inside the spark plug tubes.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 - 90" }, { interval: "100,000 km", timeLimit: "N/A", task: "PCV Spider Hose Check", details: "Replace brittle plastic PCV lines.", parts: ["Vaico PCV Hose"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 150" } ], 
