    tuningPotential: [ { stage: "Stage 1", power: "205 - 210 hp", notes: "An ME7.1.1 ECU flash via OBD2 safely optimizes ignition timing and fueling for 98 RON fuel, eliminating the slight factory restriction. The power gains are extremely minimal; it primarily improves throttle response.", zeroToHundred: "7.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "215 - 220 hp", notes: "Requires a custom performance exhaust, high-flow catalytic converters, and a cold air intake. Produces an incredible V6 sound, but the cost vastly outweighs the power gains.", zeroToHundred: "7.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Supercharger / 2.7T Swap)", power: "280 - 400+ hp", notes: "The only logical, financially sound way to make this car fast today is to swap in a 2.7T (BiTurbo).", zeroToHundred: "5.5s", hundredToTwoHundred: "15.0s" } ],
