    torqueSpecs: [ { part: "Oil Drain Plug", value: "30 Nm", note: "Replace copper crush washer." }, { part: "Spark Plugs", value: "30 Nm", note: "Torque carefully into the aluminum heads." }, { part: "Wheel Bolts", value: "120 Nm", note: "Star pattern." }, { part: "Valve Cover Nuts", value: "10 Nm", note: "Tighten evenly in a crisscross pattern. Extremely prone to snapping." }, { part: "Cam Chain Tensioner Bolts", value: "10 Nm", note: "Delicate M6 threads." }, { part: "Timing Belt Tensioner", value: "25 Nm", note: "Critical torque for the massive front belt." }, { part: "Intake Manifold Bolts", value: "20 Nm", note: "Use new gaskets." } ],
    engineeringData: { blockDesign: "All-Aluminum 90-degree V8 closed deck. Features Alusil (aluminum-silicon) cylinder liners to save weight. Barely fits into the C5 engine bay, requiring a specific wider front subframe and extended fenders compared to V6 models.", crankshaft: "Forged Steel, cross-plane design, 5 main bearings.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "150 Amp (Water-cooled on some models).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with special iron-coated skirts for the Alusil bores.", wristPinDiameter: "22 mm", connectingRodLength: "154 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "54.0 mm", rodRatio: "1.79" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-efficiency 5-valve per cylinder (40V DOHC) architecture. Maximizes high-RPM airflow.", valveSizes: "Intake: 26.9 mm (x3) / Exhaust: 29.9 mm (x2).", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad Camshafts. Intake cams driven by internal chains from the exhaust cams with variable phasing.", lifterType: "Hydraulic Lifters.", specialFeature: "Dual-stage variable geometry intake manifold for massive low-end torque." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Crankshaft driven internal gear pump.", thermostatOpening: "87°C. Buried deeply behind the timing belt.", oilCooler: "Water-to-Oil heat exchanger mounted to the block." }, fuelSystem: { systemType: "Multi-Point Injection (Motronic ME7.1).", maxPressure: "4.0 Bar (Fuel Rail).", injectors: "8x Bosch EV14 style." }, tuningLimits: { maxSafeTorqueStock: "Approx. 500 Nm (Connecting rod limit).", maxSafePowerStock: "Approx. 400 hp.", maxSafeRPM: "6800 RPM", weakestLink: "Naturally aspirated architecture entirely restricts power gains. The automatic transmission is the hard mechanical limit." }, electrical: { coils: "8x Individual Coil-on-Plug units.", ecu: "Bosch Motronic ME7.1 (Drive By Wire)" } },
    recommendedParts: { description: "The ARS 4.2 V8 is magnificent but requires a massive budget. Proactively replace the plastic oil cooler pipe and fix all oil leaks.", parts: [ { category: "Timing Belt Kit", brand: "Continental", note: "CT920K2. REQUIRES AUDI V8 CAM LOCKING TOOL." }, { category: "Billet Oil Cooler Pipe", brand: "GruvenParts", note: "Replaces the fragile plastic factory pipe. Absolutely essential." }, { category: "Cam Chain Tensioner (Left & Right)", brand: "INA", note: "Replace if rattling on startup." }, { category: "Valve Cover Gasket Set", brand: "Elring", note: "Required for tensioner job. Cures oil in spark plugs." }, { category: "Water Pump", brand: "HEPU", note: "P544. Metal impeller upgrade." }, { category: "Ignition Coil Pack", brand: "NGK", note: "U5014. Replaces cracked factory units." }, { category: "Mass Air Flow Sensor", brand: "Bosch", note: "0 280 218 017. Fixes erratic idle." }, { category: "Spark Plugs", brand: "NGK", note: "BKR6EKUB. Dual-ground electrode." }, { category: "Thermostat", brand: "Mahle", note: "TX 15 87D. Change ONLY when doing timing belt." } ] },
