    tuningPotential: [ { stage: "Stage 1", power: "310 - 315 hp", notes: "An ME7.1.1 ECU flash via OBD2 optimizes ignition timing and fueling for 98 RON fuel. The power gains are negligible; it primarily sharpens the Drive-By-Wire throttle response.", zeroToHundred: "6.7s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "320 - 330 hp", notes: "Requires a custom performance exhaust, high-flow catalytic converters, and a cold air intake. Produces an earth-shattering V8 sound, but the cost vastly outweighs the horsepower gains.", zeroToHundred: "6.4s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Supercharger)", power: "400 - 450 hp", notes: "Roots-style supercharger kits exist for the 40V V8, but they cost significantly more than the value of the entire car and will instantly shatter the 5HP24A automatic transmission.", zeroToHundred: "5.2s", hundredToTwoHundred: "13.0s" } ],
