        ignitionAndEngine: [ { interval: "150,000 km", timeLimit: "N/A", task: "Timing Chain Service", details: "The 'Engine-Out' service. Replace all rear timing chains and plastic guides.", parts: ["Complete Chain Kit"], importance: "Critical", laborDifficulty: "Extreme", estimatedCost: "3500 - 5000" }, { interval: "60,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace all 8 plugs.", parts: ["8x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 - 120" } ], 
        preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "N/A", task: "Suspension Bushings", details: "The massive V8 destroys front multi-link control arm bushings.", parts: ["Control Arm Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "400 - 800" } ], 
