        engineMechanical: [ { interval: "100,000 km", timeLimit: "N/A", task: "Valve Cover Gaskets", details: "Replace on both banks.", parts: ["Gaskets"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 - 150" } ] 
