    crossReferenceParts: [ { partName: "Valve Cover Gasket Set", category: "Engine", oem: { brand: "Audi Genuine", code: "077 198 025 B", approxPrice: "75 EUR" }, crossRef: { brand: "Elring", code: "382.750", approxPrice: "35 EUR", source: "OEM Supplier", autodoclink: "N/A", advanceautopartslink: "N/A" }, note: "Required for oil leaks." }, { partName: "Ignition Coil Pack", category: "Ignition", oem: { brand: "Audi Genuine", code: "077 905 115 C", approxPrice: "65 EUR" }, crossRef: { brand: "NGK", code: "U5014", approxPrice: "35 EUR", source: "OEM Supplier", autodoclink: "N/A", advanceautopartslink: "N/A" }, note: "Requires 8." }, { partName: "Spark Plugs", category: "Ignition", oem: { brand: "Audi Genuine", code: "101 000 035 HJ", approxPrice: "35 EUR" }, crossRef: { brand: "NGK", code: "BKR6EKUB", approxPrice: "18 EUR", source: "OEM Supplier", autodoclink: "N/A", advanceautopartslink: "N/A" }, note: "Dual-ground electrode." } ],
