    engineeringData: { blockDesign: "All-Aluminum 90-degree V6 closed deck. Features Alusil (aluminum-silicon) cylinder liners to save significant weight over the older 2.8L iron blocks, but sacrifices some structural durability.", crankshaft: "Forged Steel, cross-plane design, 4 main bearings.", pistonSpeed: "15.7 m/s @ 6000 RPM.", alternator: "120 Amp or 140 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with special iron-coated skirts to run directly on the Alusil bores.", wristPinDiameter: "21 mm", connectingRodLength: "154 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "54.0 mm", rodRatio: "1.79" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-efficiency 5-valve per cylinder (30V DOHC).", valveSizes: "Intake: 26.9 mm (x3) / Exhaust: 29.9 mm (x2).", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad Camshafts. Driven by a massive continuous timing belt.", lifterType: "Hydraulic Lifters.", specialFeature: "Continuously Variable Valve Timing (VVT) on both intake and exhaust camshafts. The BBJ uses a slightly restricted ECU map compared to the ASN." }, oilAndCooling: { oilSquirters: "Yes (Under-piston cooling jets).", oilPumpType: "Crankshaft driven internal gear pump.", thermostatOpening: "Electronically mapped. Opens mechanically at 100°C, but heated by ECU under load.", oilCooler: "Water-to-Oil heat exchanger at the oil filter base." }, fuelSystem: { systemType: "Multi-Point Injection (MPI) with Returnless Fuel Rail.", maxPressure: "4.0 Bar.", injectors: "6x Bosch EV14-style Electronic Solenoids." }, tuningLimits: { maxSafeTorqueStock: "Approx. 380 Nm.", maxSafePowerStock: "Approx. 250 hp.", maxSafeRPM: "6800 RPM", weakestLink: "The Alusil block architecture completely restricts forced induction tuning." }, electrical: { coils: "6x Individual Coil-on-Plug (COP) units.", ecu: "Bosch Motronic ME7.1.1" } },
