    tuningPotential: [ { stage: "Stage 1", power: "140 - 145 hp", notes: "An EDC15 ECU remap dramatically improves mid-range torque. The turbo boost is safely increased to ~1.1 bar.", zeroToHundred: "10.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "160 - 170 hp", notes: "Requires larger injector nozzles (.216mm from a T4) and a custom remap. The factory clutch will slip and require an upgrade.", zeroToHundred: "8.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "200+ hp", notes: "Requires a larger turbo (GT1749VB from an ARL), an 11mm injection pump head, .232 nozzles, and a front-mount intercooler. The engine block handles this effortlessly.", zeroToHundred: "6.8s", hundredToTwoHundred: "N/A" } ],
