    tuningPotential: [ { stage: "Stage 1", power: "145 - 155 hp", notes: "An EDC15P ECU remap unlocks a massive torque spike (up to 360Nm). It transforms the car but will likely cause an old Dual Mass Flywheel to shudder violently.", zeroToHundred: "9.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "170 - 180 hp", notes: "Requires a GT1749VA (130hp) or VB (150hp) turbocharger, an upgraded front-mount intercooler, and an SMF clutch kit.", zeroToHundred: "8.2s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "220 - 240+ hp", notes: "Requires ARL head bolts, larger PD injector nozzles (e.g., Firad +80%), a GTB1756VK turbo, and a 4-bar MAP sensor. The block handles this torque easily.", zeroToHundred: "6.5s", hundredToTwoHundred: "18.0s" } ],
