    tuningPotential: [ { stage: "Stage 1", power: "165 - 175 hp", notes: "An EDC15P+ ECU remap unlocks a massive, aggressive torque spike (up to 380Nm). Completely transforms the acceleration characteristics of the A6.", zeroToHundred: "8.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "185 - 195 hp", notes: "Requires a GT1749VB (PD150) turbocharger and an upgraded front-mount intercooler. The factory 6-speed clutch may start to slip.", zeroToHundred: "7.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "230 - 250+ hp", notes: "Requires ARL head bolts, larger PD injector nozzles (+80%), a GTB1756VK turbo, 4-bar MAP sensor, and an SMF clutch. The AVF block handles this power brilliantly.", zeroToHundred: "6.2s", hundredToTwoHundred: "17.0s" } ],
