    tuningPotential: [ { stage: "Stage 1", power: "165 - 170 hp", notes: "An EDC15P+ ECU remap unlocks significant torque. HOWEVER, because the AWX uses a smaller 228mm clutch and 5-speed box, tuners must intentionally limit the torque spike to save the clutch.", zeroToHundred: "9.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "180 - 190 hp", notes: "Requires a GT1749VB (PD150) turbocharger. A clutch upgrade is absolutely mandatory at this stage for the AWX.", zeroToHundred: "8.2s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "230 - 250+ hp", notes: "Requires ARL head bolts, larger PD injector nozzles (+80%), a GTB1756VK turbo, 4-bar MAP sensor, and a heavy-duty clutch kit.", zeroToHundred: "6.5s", hundredToTwoHundred: "17.5s" } ],
