    engineeringData: { blockDesign: "Cast Iron 90-degree V6 closed deck. Features thick cylinder walls to handle diesel compression.", crankshaft: "Forged Steel, 4 main bearings.", pistonSpeed: "13.5 m/s @ 4000 RPM.", alternator: "120 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling gallery and combustion bowl.", wristPinDiameter: "30 mm", connectingRodLength: "144 mm", rodBoltSize: "M9 x 1.0", crankMainJournal: "60.0 mm", crankRodJournal: "50.0 mm", rodRatio: "1.67" }, cylinderHead: { combustionChamberVol: "N/A (In piston bowl)", intakePortFlow: "24-valve DOHC crossflow. 4 valves per cylinder.", valveSizes: "Intake: 28.5 mm (x2) / Exhaust: 28.5 mm (x2).", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad Camshafts. Early sliding rocker design, inherently flawed regarding lubrication and wear.", lifterType: "Hydraulic Lifters with sliding pads.", specialFeature: "Central vertical injector placement for optimal fuel atomization." }, oilAndCooling: { oilSquirters: "Yes (Under-piston cooling jets).", oilPumpType: "Chain-driven internal gear pump.", thermostatOpening: "87°C. Requires timing belt removal to replace.", oilCooler: "Water-to-Oil heat exchanger in the engine valley." }, fuelSystem: { systemType: "Direct Injection via Bosch VP44 Radial Piston Distributor Pump.", maxPressure: "Approx. 1850 Bar.", injectors: "Mechanical 2-stage spring injectors (Injector #3 has needle lift sensor)." }, tuningLimits: { maxSafeTorqueStock: "Approx. 420 Nm (Clutch/Transmission limit).", maxSafePowerStock: "Approx. 210 hp (VP44 fueling limit).", maxSafeRPM: "4500 RPM", weakestLink: "The VP44 injection pump physically cannot supply enough fuel for massive power, and the sliding camshafts will wear rapidly under high stress." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC15M" } },
