        transmission: { manual: { name: "01E - 6-Speed Manual", torqueLimit: "450+ Nm (Gearbox) / 380 Nm (Clutch)", oilType: "API GL-4 SAE 75W-90", note: "The highly desirable 6-speed manual. Extremely robust and handles the 370 Nm torque perfectly." }, automatics: [ { name: "01V Tiptronic (Quattro)", torqueLimit: "380 Nm", oilType: "ZF Lifeguard 5", note: "Quattro models use the ZF 5HP. The heavy torque of the AKE pushes this transmission to its absolute limit." } ] },
