            { partName: "Needle Lift Sensor Injector", category: "Fuel System", oem: { brand: "Audi Genuine", code: "059 130 202 G", approxPrice: "450 EUR" }, crossRef: { brand: "Bosch", code: "0 432 133 837", approxPrice: "250 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059130202g", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059130202g" }, note: "Injector #3 with G80 sensor." }
