            ignitionAndEngine: [ { interval: "60,000 km", timeLimit: "4 years", task: "Timing Belt, Water Pump & Thermostat", details: "Shortened interval for the RS6. Entire front clip must be removed.", parts: ["Timing Kit", "Pump", "Thermostat"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "1200 - 1800" }, { interval: "40,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "Turbos blow out spark easily under 1+ bar of boost.", parts: ["8x NGK PFR6Q"], importance: "High", laborDifficulty: "Easy", estimatedCost: "100 - 140" }, { interval: "Annually", timeLimit: "N/A", task: "Boost Leak Test", details: "Pressurize system to find torn hoses and bad diverter valves.", parts: ["Silicone Hoses"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "Free - 80" } ], 
