            tuningPotential: [ { stage: "Stage 1", power: "210 - 220 hp", notes: "An MED9 ECU flash yields massive gains. The K03 turbo spools instantly. A Revision D diverter valve is mandatory to hold the boost.", zeroToHundred: "7.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "230 - 245 hp", notes: "Requires a 3-inch downpipe, high-flow cat, upgraded intake, and HPFP internals to maintain rail pressure.", zeroToHundred: "6.8s", hundredToTwoHundred: "18.0s" }, { stage: "Stage 3 (K04 Turbo Swap)", power: "300 - 330 hp", notes: "Swapping to a BorgWarner K04 (from the S3/Edition 30) along with S3 injectors, RS4 PRV, and a larger intercooler. Turns the A6 into a genuine sleeper.", zeroToHundred: "5.8s", hundredToTwoHundred: "14.5s" } ],
