                tuningPotential: [ { stage: "Stage 1", power: "390 - 410 hp", notes: "An ECU flash only. The supercharger generates significantly more boost. Transforms the car entirely.", zeroToHundred: "5.2s", hundredToTwoHundred: "12.5s" }, { stage: "Stage 2", power: "440 - 460 hp", notes: "Requires a smaller supercharger pulley and an upgraded heat exchanger to prevent heat soak. A TCU tune for the ZF 6HP is mandatory here.", zeroToHundred: "4.6s", hundredToTwoHundred: "10.8s" }, { stage: "Stage 3 (Dual Pulley)", power: "480 - 520+ hp", notes: "Requires upgrading BOTH the supercharger and crank pulleys, high-flow catalytic converters (test pipes), and a massive cooling setup. The EA837 block handles this effortlessly.", zeroToHundred: "4.1s", hundredToTwoHundred: "9.2s" } ],
