                tuningPotential: [ { stage: "Stage 1", power: "450 - 460 hp", notes: "ECU flash unlocks minor gains, mostly improving throttle response and removing the speed limiter. Very little peak power to be found naturally aspirated.", zeroToHundred: "5.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "465 - 475 hp", notes: "Requires a full custom exhaust, high-flow cats, and intake modifications. Produces one of the greatest engine sounds on earth, but costs thousands for 20hp.", zeroToHundred: "4.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "N/A", notes: "Forced induction is essentially impossible due to the complete lack of space in the C6 engine bay and the fragility of the Alusil block.", zeroToHundred: "N/A", hundredToTwoHundred: "N/A" } ],
