                engineeringData: { blockDesign: "Cast Iron inline-4 closed deck. Extremely durable base architecture designed for immense cylinder pressures.", crankshaft: "Forged Steel, 5 main bearings.", pistonSpeed: "14.5 m/s @ 4500 RPM.", alternator: "140 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with combustion bowl.", wristPinDiameter: "26 mm", connectingRodLength: "144 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "54.0 mm", crankRodJournal: "47.8 mm", rodRatio: "1.67" }, cylinderHead: { combustionChamberVol: "N/A (In piston bowl)", intakePortFlow: "16-valve DOHC crossflow. 4 valves per cylinder.", valveSizes: "Intake: 26.6 mm / Exhaust: 26.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Dual Overhead Camshafts. Exhaust cam actuates the PD unit injectors.", lifterType: "Hydraulic Lifters with roller rockers.", specialFeature: "Pump Düse (Unit Injector) technology generates incredibly high injection pressures mechanically, bypassing the need for a common rail." }, oilAndCooling: { oilSquirters: "Yes (Under-piston cooling jets).", oilPumpType: "Gear-driven balance shaft module with integrated oil pump (Utilizes the flawed 77mm hex key).", thermostatOpening: "87°C.", oilCooler: "Water-to-Oil heat exchanger at the oil filter base." }, fuelSystem: { systemType: "Direct Injection via Cam-Actuated Unit Injectors (Pump Düse).", maxPressure: "2050 Bar.", injectors: "Bosch Solenoid Unit Injectors." }, tuningLimits: { maxSafeTorqueStock: "Approx. 400 Nm (Clutch/DMF limit).", maxSafePowerStock: "Approx. 180 hp (Turbo flow limit).", maxSafeRPM: "4500 RPM", weakestLink: "The oil pump hex key and the Dual Mass Flywheel. The factory turbo is undersized compared to the 170hp variants." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC16U31" } },
