                sisterModels: [ { name: "Audi A4 (B8) 2.0 TDI", note: "The CAHB was a common tax-bracket detuned version in European markets, sharing all hardware with the 170hp CAHA." } ],
                tuningPotential: [ { stage: "Stage 1", power: "200 - 210 hp", notes: "Because the CAHB is artificially detuned via software, an EDC17 ECU remap safely brings this engine well past the factory 170hp version, transforming its pulling power.", zeroToHundred: "8.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "215 - 225 hp", notes: "Requires a turbo-back exhaust (or DPF/Cat delete where legal). The factory turbocharger is highly restrictive at this level.", zeroToHundred: "7.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "240 - 260+ hp", notes: "Requires a CP3 high-pressure fuel pump conversion (mandatory for fuel volume and safety), a GTB1756VK turbo upgrade, and an upgraded clutch.", zeroToHundred: "6.3s", hundredToTwoHundred: "17.5s" } ],
