    sisterModels: [ { name: "Audi A4 (B7) 3.0 TDI", note: "The ASB engine is the most popular 3.0 TDI variant in the B7 chassis." }, { name: "Volkswagen Touareg 3.0 V6 TDI", note: "Utilized the same core EA896 engine architecture." } ],
    tuningPotential: [ { stage: "Stage 1", power: "275 - 285 hp", notes: "An EDC16 remap adds a colossal amount of torque (approx. 560 Nm). Very safe on stock hardware, but the ZF6 auto benefits greatly from a TCU tune to increase line pressure.", zeroToHundred: "6.6s", hundredToTwoHundred: "18.0s" }, { stage: "Stage 2", power: "300 - 315 hp", notes: "Requires DPF/EGR delete, upgraded intercooler, and a custom 3-inch exhaust. The factory BV50 turbo reaches its maximum efficiency here.", zeroToHundred: "6.0s", hundredToTwoHundred: "14.5s" }, { stage: "Stage 3", power: "350 - 370+ hp", notes: "Requires a GTB2260VK or hybrid turbo swap, 4 BAR MAP sensor, CP3 fuel pump upgrades, and a fully built transmission to prevent clutch pack failure.", zeroToHundred: "5.4s", hundredToTwoHundred: "12.5s" } ],
