    tuningPotential: [ { stage: "Stage 1", power: "295 - 310 hp", notes: "The CDYA responds exceptionally well to tuning. An EDC17 remap brings it to 300+ hp and 600+ Nm effortlessly.", zeroToHundred: "6.1s", hundredToTwoHundred: "14.5s" }, { stage: "Stage 2", power: "320 - 330 hp", notes: "Requires DPF removal, Wagner intercooler, and exhaust mods. The factory turbocharger reaches its absolute limit here.", zeroToHundred: "5.7s", hundredToTwoHundred: "13.0s" }, { stage: "Stage 3", power: "370 - 400+ hp", notes: "Requires a CP3 fuel pump conversion (mandatory to flow enough fuel safely), GTB2260VK hybrid turbo, and a built ZF 6HP transmission.", zeroToHundred: "5.0s", hundredToTwoHundred: "11.2s" } ],
