    tuningPotential: [ { stage: "Stage 1", power: "240 - 250 hp", notes: "An ECU flash transforms this engine. Because it shares the exact same block as the 2.0 TFSI, the 1.8 responds massively to software, yielding 380+ Nm of torque instantly.", zeroToHundred: "6.8s", hundredToTwoHundred: "18.5s" }, { stage: "Stage 2", power: "260 - 275 hp", notes: "Requires a 3-inch downpipe, high-flow catalytic converter, and an upgraded intake. The factory IS12 turbo reaches its maximum efficiency limit here.", zeroToHundred: "6.2s", hundredToTwoHundred: "16.0s" }, { stage: "Stage 3 (IS20/IS38 Swap)", power: "320 - 350+ hp", notes: "Swapping to the IS20 (from the 2.0 TFSI) or the IS38 (from the S3/Golf R) turns this into a monster. Requires an upgraded intercooler and a DL382 TCU tune to increase clamping pressure.", zeroToHundred: "5.4s", hundredToTwoHundred: "12.8s" } ],
