    tuningPotential: [ { stage: "Stage 1", power: "245 - 255 hp", notes: "Due to the extreme 11.7:1 compression ratio, tuning must be handled very carefully to avoid knock. A 98+ RON map is absolutely mandatory. Yields approx 400 Nm.", zeroToHundred: "6.9s", hundredToTwoHundred: "19.5s" }, { stage: "Stage 2", power: "270 - 285 hp", notes: "Requires a 3-inch downpipe, high-flow catalytic converter, and an upgraded intercooler. The high compression ratio severely limits further safe power gains on pump gas.", zeroToHundred: "6.3s", hundredToTwoHundred: "16.8s" }, { stage: "Stage 3 (IS20 Swap)", power: "320 - 340 hp", notes: "Swapping to the IS20 turbo requires extreme caution, water/meth injection, and very conservative ignition timing to prevent blowing the ring lands.", zeroToHundred: "5.5s", hundredToTwoHundred: "13.2s" } ],
