    tuningPotential: [ { stage: "Stage 1", power: "285 - 295 hp", notes: "An ECU flash provides excellent gains for the ICE component. However, the hybrid control module may intervene if torque spikes too sharply. You MUST ensure the timing chain tensioner is updated first.", zeroToHundred: "6.5s", hundredToTwoHundred: "18.5s" }, { stage: "Stage 2", power: "310 - 325 hp", notes: "Requires a high-flow downpipe and upgraded intake. Torque delivery must be mapped smoothly to avoid damaging the hybrid coupling clutch.", zeroToHundred: "6.0s", hundredToTwoHundred: "16.0s" }, { stage: "Stage 3 (K04 Swap)", power: "360 - 380 hp", notes: "Swapping to a K04 turbocharger. Very complex to tune successfully alongside the hybrid system. High risk of transmission clutch slip.", zeroToHundred: "5.5s", hundredToTwoHundred: "14.2s" } ],
