    tuningPotential: [ { stage: "Stage 1", power: "215 - 220 hp", notes: "Naturally aspirated engines yield terrible returns on ECU tuning. You will pay hundreds of dollars for 10-15 horsepower and slightly sharper throttle response. Not recommended.", zeroToHundred: "7.7s", hundredToTwoHundred: "23.0s" }, { stage: "Stage 2", power: "225 - 235 hp", notes: "Requires a custom exhaust, high-flow catalytic converters, and an intake. Extremely expensive for barely noticeable gains.", zeroToHundred: "7.4s", hundredToTwoHundred: "21.5s" }, { stage: "Stage 3 (Supercharger)", power: "320 - 350 hp", notes: "Custom supercharger setups exist for the EA837, but attempting to run this power through the factory Multitronic CVT will instantly destroy the transmission.", zeroToHundred: "5.8s", hundredToTwoHundred: "14.8s" } ],
