    sisterModels: [ { name: "Audi S4 (B8) 3.0 TFSI", note: "The CGWD is fundamentally identical to the S4's engine." }, { name: "Audi A7 (4G) 3.0 TFSI", note: "Shares the exact same platform and powertrain." } ],
    tuningPotential: [ { stage: "Stage 1", power: "390 - 410 hp", notes: "An ECU software flash alone yields an incredible 100 horsepower gain. A TCU tune for the DL501 is highly recommended to improve shift speed and clamping force.", zeroToHundred: "4.7s", hundredToTwoHundred: "12.3s" }, { stage: "Stage 2 (Single/Dual Pulley)", power: "440 - 470 hp", notes: "Requires upgrading the supercharger pulley (and optionally the crank pulley), a massive aftermarket heat exchanger (HX), and a mandatory TCU tune.", zeroToHundred: "4.0s", hundredToTwoHundred: "9.8s" }, { stage: "Stage 3 (Ported Supercharger/Ultracharger)", power: "500 - 550+ hp", notes: "Requires a ported supercharger or larger throttle body (Ultracharger), upgraded high-pressure fuel pump (HPFP), test pipes, and an extreme cooling setup. Stock block handles this effortlessly.", zeroToHundred: "3.4s", hundredToTwoHundred: "8.3s" } ],
