    model3DPath: "/images/brands/audi/A6/C7/talan.glb", model3DScale: 0.25, model3DRotation: [0, 3.14, 0], manualLightPositions: { headlights: { x: 0.16 , y: -0.01, z: 0.52 } }, riskRating: 5, lightSettings: { headlightAngle: 0.25, headlightIntensity: 200, headlightOpacity: 0.5, headlightRadiusTop: 0.02, headlightTargetDistance: 4.5, headlightPenumbra: 0.1, meshGlowHeadlight: 10, meshGlowTaillight: 20, meshGlowDrl: 8, useBloom: true }, hotspotSettings: {}, 
