    tuningPotential: [ { stage: "Stage 1", power: "420 - 440 hp", notes: "An ECU software flash yields an incredible 100+ horsepower gain. The EVO engine breathes extremely well. A TCU tune for the DL501 is highly recommended.", zeroToHundred: "4.5s", hundredToTwoHundred: "11.5s" }, { stage: "Stage 2 (Single/Dual Pulley)", power: "470 - 490 hp", notes: "CRITICAL: You MUST pin or weld the factory magnetic supercharger clutch, otherwise it will instantly slip and burn out. Requires massive cooling upgrades.", zeroToHundred: "3.8s", hundredToTwoHundred: "9.2s" }, { stage: "Stage 3 (Ported Supercharger/Ultracharger)", power: "550 - 580+ hp", notes: "Requires a ported supercharger, upgraded high-pressure fuel pump, pinned SC clutch, test pipes, and extreme cooling. The EVO block handles this power effortlessly.", zeroToHundred: "3.2s", hundredToTwoHundred: "7.8s" } ],
