    tuningPotential: [ { stage: "Stage 1", power: "210 - 215 hp", notes: "An EDC17 ECU remap provides a massive bump in mid-range torque and top-end power. The Common Rail injection makes the power delivery incredibly smooth.", zeroToHundred: "7.7s", hundredToTwoHundred: "18.5s" }, { stage: "Stage 2", power: "225 - 235 hp", notes: "Requires a turbo-back exhaust (or DPF/EGR delete). The factory turbocharger is highly restrictive past this level.", zeroToHundred: "7.2s", hundredToTwoHundred: "17.0s" }, { stage: "Stage 3", power: "260 - 280+ hp", notes: "Requires a CP3 high-pressure fuel pump conversion (mandatory for fuel volume and safety), a GTB1756VK or GTB2056 turbo upgrade, and an upgraded clutch.", zeroToHundred: "6.1s", hundredToTwoHundred: "14.5s" } ],
