    tuningPotential: [ { stage: "Stage 1", power: "210 - 215 hp", notes: "Because the CGLD is software-detuned from the factory to hit a specific 163hp tax bracket, an EDC17 remap leaps straight past the 177hp models to 210hp.", zeroToHundred: "7.7s", hundredToTwoHundred: "18.5s" }, { stage: "Stage 2", power: "225 - 235 hp", notes: "Requires a turbo-back exhaust. Do not attempt if equipped with the Multitronic CVT, it will slip under the torque.", zeroToHundred: "7.2s", hundredToTwoHundred: "17.0s" }, { stage: "Stage 3", power: "260 - 280+ hp", notes: "Requires a CP3 high-pressure fuel pump conversion (mandatory for fuel volume), a GTB1756VK turbo upgrade, and an upgraded clutch.", zeroToHundred: "6.1s", hundredToTwoHundred: "14.5s" } ],
