    tuningPotential: [ { stage: "Stage 1", power: "220 - 230 hp", notes: "An EDC17 ECU remap transforms this engine, safely bringing it to 450 Nm of torque. The EA288 block handles this power effortlessly.", zeroToHundred: "7.3s", hundredToTwoHundred: "18.5s" }, { stage: "Stage 2", power: "240 - 250 hp", notes: "Requires a DPF/SCR delete (where legal) and a turbo-back exhaust. The factory water-cooled intercooler is excellent.", zeroToHundred: "6.8s", hundredToTwoHundred: "16.5s" }, { stage: "Stage 3", power: "270 - 290+ hp", notes: "Requires a GTD1752VRK turbo upgrade, larger injectors, and an upgraded clutch/TCU tune.", zeroToHundred: "6.0s", hundredToTwoHundred: "14.0s" } ],
