    tuningPotential: [ { stage: "Stage 1", power: "295 - 310 hp", notes: "An EDC17 ECU remap completely transforms this car, delivering over 620 Nm of torque. It feels significantly faster than stock and improves fuel economy. SCR mapping must be considered.", zeroToHundred: "5.8s", hundredToTwoHundred: "14.5s" }, { stage: "Stage 2", power: "330 - 350 hp", notes: "Requires DPF removal, SCR delete (where legal), and an upgraded intercooler. The factory turbocharger reaches its absolute limit here. TCU tune highly recommended.", zeroToHundred: "5.3s", hundredToTwoHundred: "12.8s" }, { stage: "Stage 3", power: "400 - 430+ hp", notes: "Requires GTB2260VK hybrid turbo, a mandatory CP3 fuel pump conversion, upgraded map sensor, and a transmission clutch upgrade with aggressive TCU tuning.", zeroToHundred: "4.5s", hundredToTwoHundred: "10.5s" } ],
