    engineeringData: { blockDesign: "Cast Iron 90-degree V6 closed deck (EA897evo). Incredibly dense and heavy, designed for extreme cylinder pressures.", crankshaft: "Forged Steel, 4 main bearings.", pistonSpeed: "14.2 m/s @ 4500 RPM.", alternator: "180 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling channels.", wristPinDiameter: "30 mm", connectingRodLength: "154 mm", rodBoltSize: "M9 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "60.0 mm", rodRatio: "1.79" }, cylinderHead: { combustionChamberVol: "In piston bowl", intakePortFlow: "24-valve DOHC crossflow.", valveSizes: "Intake: 29.0 mm / Exhaust: 26.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad cams driven by 4 rear chains. Features hollow-cast camshafts to reduce weight.", lifterType: "Hydraulic roller rockers.", specialFeature: "Piezo injectors can trigger up to 5 individual injection events per cycle for extreme noise reduction and efficiency." }, oilAndCooling: { oilSquirters: "Yes (Under-piston cooling jets).", oilPumpType: "Chain-driven fully variable.", thermostatOpening: "87°C.", oilCooler: "Water-to-Oil heat exchanger located deep in the engine V-valley." }, fuelSystem: { systemType: "Common Rail. Bosch CP4.2 Dual-Plunger High-Pressure Fuel Pump. Features Euro 6 SCR AdBlue injection.", maxPressure: "2000 Bar.", injectors: "Bosch Piezoelectric." }, tuningLimits: { maxSafeTorqueStock: "Approx. 550 Nm (DL382 clutch limit)", maxSafePowerStock: "Approx. 340 hp (Turbo limit)", maxSafeRPM: "4800 RPM", weakestLink: "The Bosch CP4.2 fuel pump, the AdBlue system, and the DL382 transmission clutch clamping pressure." }, electrical: { coils: "Compression Ignition", ecu: "Bosch EDC17CP54" } },
