    tuningPotential: [ { stage: "Stage 1", power: "300 - 320 hp", notes: "Because the CZVA is artificially detuned via software, an ECU remap safely brings this engine well past the factory 272hp version, offering phenomenal value.", zeroToHundred: "5.8s", hundredToTwoHundred: "14.8s" }, { stage: "Stage 2", power: "330 - 345 hp", notes: "Requires DPF removal, SCR delete, and exhaust mods. The factory turbocharger reaches its limit here. DL382 TCU tune is mandatory to prevent clutch slip.", zeroToHundred: "5.2s", hundredToTwoHundred: "13.0s" }, { stage: "Stage 3", power: "380 - 410+ hp", notes: "Requires GTB2260VK hybrid turbo, CP3 fuel pump conversion, and highly upgraded S Tronic clutches.", zeroToHundred: "4.6s", hundredToTwoHundred: "10.9s" } ],
