    tuningPotential: [ { stage: "Stage 1", power: "370 - 380 hp", notes: "An EDC17 ECU remap transforms this engine into an absolute monster, pushing torque past 750 Nm. The ZF 8HP handles it perfectly.", zeroToHundred: "4.8s", hundredToTwoHundred: "12.5s" }, { stage: "Stage 2", power: "400 - 415 hp", notes: "Requires DPF removal, EGR delete, and an upgraded Wagner intercooler. This is the safe limit for the factory high-pressure turbo.", zeroToHundred: "4.4s", hundredToTwoHundred: "11.2s" }, { stage: "Stage 3", power: "480 - 500+ hp", notes: "Requires hybrid turbos, a mandatory CP3 fuel pump conversion (the CP4 cannot flow enough fuel), upgraded MAP sensor, and a ZF8 TCU tune.", zeroToHundred: "3.8s", hundredToTwoHundred: "9.5s" } ],
