    tuningPotential: [ { stage: "Stage 1", power: "380 - 390 hp", notes: "An EDC17 ECU remap transforms this engine into an absolute monster, pushing torque past 750 Nm. The ZF 8HP handles it perfectly. SCR mapping must be considered.", zeroToHundred: "4.7s", hundredToTwoHundred: "12.3s" }, { stage: "Stage 2", power: "410 - 420 hp", notes: "Requires DPF removal, SCR delete (where legal), and an upgraded Wagner intercooler. This is the safe limit for the factory high-pressure turbo.", zeroToHundred: "4.3s", hundredToTwoHundred: "11.0s" }, { stage: "Stage 3", power: "480 - 500+ hp", notes: "Requires hybrid turbos, a mandatory CP3 fuel pump conversion (the CP4 cannot flow enough fuel), upgraded MAP sensor, and a ZF8 TCU tune.", zeroToHundred: "3.7s", hundredToTwoHundred: "9.3s" } ],
