        { name: "CP4 Disaster Prevention Kit", description: "Installing a bypass filter that routes fuel from the CP4 pump back to the tank instead of the injectors in the event of a failure.", benefit: "Saves the extremely expensive Piezo injectors and fuel rails if the high-pressure fuel pump self-destructs." }, 
        { name: "CP3 Fuel Pump Conversion", description: "Removing the fragile Bosch CP4 pump and retrofitting the older, bulletproof Bosch CP3 pump.", benefit: "The ultimate reliability upgrade, completely eliminating the fear of metal shavings destroying the engine. Mandatory for Stage 3." }, 
        { name: "Wagner Tuning Intercooler", description: "Upgrading the factory front-mount intercooler.", benefit: "Drastically lowers Intake Air Temperatures (IATs), preventing heat soak during repeated heavy acceleration." } 
