    tuningPotential: [ { stage: "Stage 1", power: "390 - 400 hp", notes: "An EDC17 ECU remap transforms this engine into an absolute monster, pushing torque past 760 Nm. The ZF 8HP handles it perfectly. SCR mapping must be considered.", zeroToHundred: "4.6s", hundredToTwoHundred: "12.0s" }, { stage: "Stage 2", power: "415 - 430 hp", notes: "Requires DPF removal, SCR delete (where legal), and an upgraded Wagner intercooler. This is the safe limit for the factory high-pressure turbo.", zeroToHundred: "4.3s", hundredToTwoHundred: "10.8s" }, { stage: "Stage 3", power: "480 - 520+ hp", notes: "Requires hybrid turbos, a mandatory CP3 fuel pump conversion (the CP4 cannot flow enough fuel), upgraded MAP sensor, and a ZF8 TCU tune.", zeroToHundred: "3.7s", hundredToTwoHundred: "9.3s" } ],
