    tuningPotential: [ { stage: "Stage 1", power: "510 - 530 hp", notes: "An ECU flash transforms this engine. You gain over 100hp instantly. A DL501 TCU tune is MANDATORY to increase clutch clamping pressure, or the DSG will slip.", zeroToHundred: "3.7s", hundredToTwoHundred: "9.2s" }, { stage: "Stage 2", power: "550 - 570 hp", notes: "Requires downpipes (sports cats or decat) and an upgraded air-to-water intercooler system. The tiny factory S6 turbos are completely maxed out here.", zeroToHundred: "3.4s", hundredToTwoHundred: "8.5s" }, { stage: "Stage 3 (RS6 Turbo Swap)", power: "650 - 700+ hp", notes: "Bolting on factory RS6 turbos or TSG units. Requires upgraded HPFPs, massive cooling, and an aggressive TCU tune. The S6 engine handles this effortlessly.", zeroToHundred: "2.9s", hundredToTwoHundred: "6.8s" } ],
