    tuningPotential: [ { stage: "Stage 1", power: "530 - 550 hp", notes: "An ECU flash transforms this engine. You gain over 100hp instantly. A DL501 TCU tune is MANDATORY to increase clutch clamping pressure, or the DSG will slip.", zeroToHundred: "3.6s", hundredToTwoHundred: "9.0s" }, { stage: "Stage 2", power: "570 - 590 hp", notes: "Requires downpipes (sports cats or decat) and an upgraded air-to-water intercooler system. The tiny factory S6 turbos are completely maxed out here.", zeroToHundred: "3.3s", hundredToTwoHundred: "8.3s" }, { stage: "Stage 3 (RS6 Turbo Swap)", power: "650 - 700+ hp", notes: "Bolting on factory RS6 turbos or TSG units. Requires upgraded HPFPs, massive cooling, and an aggressive TCU tune. The S6 engine handles this effortlessly.", zeroToHundred: "2.8s", hundredToTwoHundred: "6.6s" } ],
