    tuningPotential: [ { stage: "Stage 1", power: "680 - 700 hp", notes: "An ECU flash turns the RS6 into a hypercar. You gain over 120hp instantly. The ZF 8HP handles the massive 850+ Nm of torque beautifully.", zeroToHundred: "3.2s", hundredToTwoHundred: "7.0s" }, { stage: "Stage 2", power: "720 - 750 hp", notes: "Requires high-flow downpipes (sports cats or decat) and an upgraded air-to-water intercooler system. The factory RS6 turbos reach their efficiency limit here.", zeroToHundred: "2.9s", hundredToTwoHundred: "6.2s" }, { stage: "Stage 3 (TTE Turbos)", power: "850 - 900+ hp", notes: "Requires hybrid turbos (e.g., TTE800/TTE1000), upgraded HPFPs, massive cooling, and an aggressive ZF8 TCU tune. The stock block handles this extreme power without opening the engine.", zeroToHundred: "2.6s", hundredToTwoHundred: "5.5s" } ],
