    tuningPotential: [ { stage: "Stage 1", power: "700 - 720 hp", notes: "An ECU flash turns the RS6 Performance into an absolute hypercar. You gain over 100hp instantly. The ZF 8HP handles the massive 900+ Nm of torque beautifully.", zeroToHundred: "3.1s", hundredToTwoHundred: "6.8s" }, { stage: "Stage 2", power: "740 - 780 hp", notes: "Requires high-flow downpipes (sports cats or decat) and an upgraded air-to-water intercooler system. The factory RS6 turbos reach their absolute efficiency limit here.", zeroToHundred: "2.8s", hundredToTwoHundred: "6.0s" }, { stage: "Stage 3 (TTE Turbos)", power: "850 - 950+ hp", notes: "Requires hybrid turbos (e.g., TTE800/TTE1000), upgraded HPFPs, massive cooling, and an aggressive ZF8 TCU tune. The stock block handles this extreme power without opening the engine.", zeroToHundred: "2.5s", hundredToTwoHundred: "5.2s" } ],
